INSERT INTO site_pages (slug, meta_title, meta_description, content) VALUES
('home', 'Build with Certainty | John Buchan Homes', 'On your lot. To your standard. Custom homes on the Seattle Eastside since 1961.',
'{"hero":{"eyebrow":"Building since 1961 · Seattle Eastside","title":"Build with certainty.","title_emphasis":"Live exceptionally.","subtitle":"Custom homes and major renovations, built on thoughtful planning, expert guidance, and uncompromising craftsmanship, proudly serving Bellevue and the Eastside.","image_url":"/assets/ph-arch-1.png","marquee":"","cta_primary_url":"#featured-work","cta_primary_label":"Explore Our Work"},"credibility_line":"Family-owned since 1961 | 4,000+ homes built | Serving Bellevue and the Eastside","credibility_stats":[{"label":"Family-owned since 1961"},{"label":"4,000+ homes built"},{"label":"Serving Bellevue and the Eastside"}],"featured_work":{"eyebrow":"Featured Work","title":"Homes as unique as the people who live in them.","body":"Each home we build is a reflection of our clients'' vision and our commitment to timeless design, enduring quality, and meticulous attention to detail.","cta_label":"View Our Work","cta_link":"/portfolio"},"difference_section":{"eyebrow":"The John Buchan Difference","title":"What you can''t see makes all the difference.","body":"For over six decades, we''ve built a legacy of trust by doing what''s right, even when it costs more and no one sees it.\n\nFrom the framing to the finishing touches, our commitment to integrity and quality is behind every wall, so you can have complete confidence in the process and the relationship that builds your home.","image_url":"/assets/ph-arch-3.png","cta_label":"Learn More","cta_link":"/why-choose-buchan"},"what_we_do":{"eyebrow":"Our Services","title":"A full-service experience.","title_emphasis":"Thoughtfully delivered.","primary":[{"title":"Custom Homes","description":"Beautifully designed. Expertly built. Precisely planned from start to finish.","image_url":"/assets/ph-arch-1.png","link":"/custom-homes","icon":"custom-home","cta_label":"Explore Custom Homes"},{"title":"Major Renovations","description":"Reimagine your home with seamless additions and whole-home transformations.","image_url":"/assets/ph-arch-2.png","link":"/renovations","icon":"renovation","cta_label":"Explore Renovations"}],"secondary":[{"title":"ADUs & DADUs","description":"Smart spaces for extended living and added value.","link":"/services/adus","icon":"adu"},{"title":"Fire Restoration","description":"Compassionate support. Expert restoration.","link":"/services/fire-restoration","icon":"fire-restoration"},{"title":"Real Estate Services","description":"Guidance for buying, selling, and property strategy.","link":"/services/real-estate","icon":"real-estate"},{"title":"Maintenance & Service","description":"Protect your investment with proactive care.","link":"/services/home-care","icon":"maintenance"}],"preconstruction":{"title":"Plan Before You Build","body":"Preconstruction brings clarity, alignment, and confidence before a single day on site.","cta_label":"Explore Preconstruction","cta_link":"/preconstruction","image_url":"/assets/ph-arch-2.png"}},"client_concerns":{"eyebrow":"Questions Prospective Clients Are Asking","title":"","items":[{"title":"How do we establish a realistic investment?","body":"We start with your vision and priorities, then clarify scope, timeline, and investment ranges early, so you can make confident decisions without surprises."},{"title":"How will the team stay aligned?","body":"Through collaborative planning, clear communication, and shared accountability, so decisions are informed, timely, and in service of your goals."},{"title":"What makes a John Buchan home perform differently over time?","body":"It''s the combination of thoughtful design, quality construction, and proactive care, built to endure beautifully and efficiently for generations."}]},"better_planned_path":{"eyebrow":"Our Process","title":"A custom experience,","title_emphasis":"thoughtfully managed.","intro":"An aligned team. Early clarity. And steady communication at every step. We make the process predictable and the experience exceptional, so you can enjoy the journey as much as the destination.","team_heading":"One Aligned Team, Chosen for Your Home","team_body":"We collaborate with independent architects on every project and interior designers on most. Clients may bring their own trusted professionals. Buchan provides estimating, constructability review, schedule planning, coordination, detailed specifications, and construction leadership from the early stages.","team_image_url":"/assets/ph-arch-4.png","cta_label":"","cta_link":"/process"},"process_stages":[{"n":"01","title":"Discover & Evaluate","body":"We listen deeply, understand your vision, and evaluate your property and possibilities with honesty and care."},{"n":"02","title":"Plan & Align","body":"We shape a plan that reflects your goals, confirms investment clarity, and aligns every detail before we build."},{"n":"03","title":"Build with Discipline","body":"Our team executes with precision, protecting quality, schedule, and budget, so you feel informed and at ease."},{"n":"04","title":"Care Beyond Completion","body":"We remain a trusted partner long after move-in, ensuring your home performs beautifully for years to come."}],"quality_layers":{"eyebrow":"What You Can''t See","title":"Quality in Every Layer","body":"Great homes are built on systems, materials, and details that work together, quietly, every day.","elevation_image_url":"/assets/quality-layers-house.jpg","layers":[{"id":"water","label":"Water Management","benefit":"Thoughtful site planning and water control protect your home and your investment.","x":22,"y":28,"icon":"water"},{"id":"structure","label":"Structural Planning","benefit":"Engineered systems and precise detailing create strength, stability, and long-term performance.","x":22,"y":66,"icon":"structure"},{"id":"comfort","label":"Interior Comfort","benefit":"Healthy air, consistent temperatures, and quiet spaces designed for how you truly live.","x":78,"y":28,"icon":"comfort"},{"id":"craft","label":"Enduring Craftsmanship","benefit":"Carefully selected materials and meticulous workmanship ensure beauty that stands the test of time.","x":78,"y":66,"icon":"craft"}]},"testimonial_section":{"eyebrow":"Client Testimonials","title":"In their words.","quote":"From the first conversation to move-in and beyond, Buchan brought clarity, craftsmanship, and care. We felt guided, listened to, and completely confident in the process.","cite":", The Anderson Family, Bellevue, Washington","cta_label":"","cta_link":"/testimonials","left_image_url":"/assets/ph-arch-1.png","right_image_url":"/assets/ph-arch-4.png"},"pick_your_path":{"intro":"","title":"Choose Your Starting Point","tiles":[{"title":"I am considering building","description":"Explore ideas, understand possibilities, and take the first step with clarity.","link":"/custom-homes","icon":"building","cta_label":"Explore Your Options"},{"title":"I already own a property or have plans","description":"Bring your property or plans to life with expert guidance.","link":"/contact?service=I have plans and need a builder#inquiry","icon":"blueprint","cta_label":"Let''s Review Together"},{"title":"I am planning a major renovation","description":"Reimagine your home with craftsmanship that respects what''s already there.","link":"/renovations","icon":"hammer","cta_label":"See Renovation Services"}]},"closing_cta":{"title":"The right home begins with the right conversation.","subtitle":"Let''s talk about your vision, your property, and the experience you want to create.","primary_label":"Start a Conversation","primary_url":"/contact","phone":"425.827.2266","phone_href":"tel:4258272266","background_image_url":"/assets/ph-arch-1.png"}}'::jsonb),

('about', 'About Us', 'Three generations of Buchan craftsmen building on the Seattle Eastside since 1960.',
'{"hero":{"eyebrow":"Our Story","title":"Built on legacy.","title_emphasis":"Defined by you."},"timeline":{"eyebrow":"Timeline","title":"65 years of craft.","items":[{"year":"1960","title":"Founded","body":"John Buchan opens his first workshop in Bellevue."},{"year":"1985","title":"Second Generation","body":"David Buchan joins the family business."},{"year":"2014","title":"Design Studio","body":"In-house architecture and interiors launched."},{"year":"Today","title":"65 Years","body":"Three generations, one standard, yours."}]},"mission":{"eyebrow":"Our Mission","title":"Your standard is","title_emphasis":"our standard.","body":"We don''t build to impress other builders. We build to the standard you set, in every joint, every finish, every quiet detail.","image_url":"/assets/ph-arch-2.png"},"team":{"eyebrow":"The Team","title":"People who care","title_emphasis":"deeply.","members":[{"name":"Mischelle McCall","role":"Client Concierge","image_url":"/assets/ph-arch-1.png"},{"name":"David Buchan","role":"President","image_url":"/assets/ph-arch-1.png"},{"name":"Sarah Lindqvist","role":"Design Director","image_url":"/assets/ph-arch-1.png"},{"name":"Marcus Reyes","role":"Construction Manager","image_url":"/assets/ph-arch-1.png"}]},"giving_back":{"eyebrow":"Giving Back","title":"Building community,","title_emphasis":"not just homes.","image_url":"/assets/ph-arch-3.png"},"cta":{"join_title":"Join our team.","join_body":"We''re always looking for craftspeople who share our standard.","land_title":"We buy land.","land_body":"Have a lot on the Eastside? We''d love to hear about it."}}'::jsonb),

